import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        // Keep n - k consecutive sorted values: the max over each window of width gaps, minimized.
        int width = n - k - 1;
        if (width == 0) {
            System.out.println(0);
            return;
        }
        long[] gaps = new long[n - 1];
        for (int i = 0; i + 1 < n; i++) gaps[i] = a[i + 1] - a[i];
        int[] queue = new int[n - 1]; // indices with decreasing gaps
        int head = 0, tail = 0;
        long answer = Long.MAX_VALUE;
        for (int i = 0; i < n - 1; i++) {
            while (tail > head && gaps[queue[tail - 1]] <= gaps[i]) tail--;
            queue[tail++] = i;
            while (queue[head] <= i - width) head++;
            if (i >= width - 1) answer = Math.min(answer, gaps[queue[head]]);
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	slices.Sort(a)
	// Keep n - k consecutive sorted values: the max over each window of width gaps, minimized.
	width := n - k - 1
	if width == 0 {
		os.Stdout.WriteString("0\n")
		return
	}
	gaps := make([]int, n-1)
	for i := range gaps {
		gaps[i] = a[i+1] - a[i]
	}
	queue := make([]int, 0, n-1) // indices with decreasing gaps; queue[head:] is live
	head := 0
	answer := -1
	for i, g := range gaps {
		for len(queue) > head && gaps[queue[len(queue)-1]] <= g {
			queue = queue[:len(queue)-1]
		}
		queue = append(queue, i)
		for queue[head] <= i-width {
			head++
		}
		if i >= width-1 && (answer < 0 || gaps[queue[head]] < answer) {
			answer = gaps[queue[head]]
		}
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
